-- Migration (system): MFA login challenges and session MFA state (Phase 4.1 slice S2, docs/PHASE-4.1.md section 5, decisions D-080, D-121). Forward-only, additive: three columns and one check on the session table and ONE new table;
-- nothing existing is dropped or replaced. Opaque physical names (D-029) are generated by tools/schema/system-mfa-login.cjs (logical dictionary: SystemSchema.MfaLogin.cs). Do not edit by hand: re-run the generator.
--
-- WHAT THIS IS: a login with a required second factor creates NO session after the password step: it creates a short-lived, single-purpose CHALLENGE (only the SHA-256 of its 256-bit token is stored), bound to the user, the
-- client kind and the source address, with a small attempt budget. The session is created only after the second factor succeeded and records how: auth_methods is a bitmask (1 password, 2 totp); a session that has the totp bit
-- must carry the time of the verification. purpose: 0 login, 1 enrol, 2 recovery request.

ALTER TABLE t_5a3ce63e
    ADD COLUMN c_b205a259 timestamptz NULL,
    ADD COLUMN c_a9f03684 smallint NOT NULL DEFAULT 1,
    ADD COLUMN c_d5163777 boolean NOT NULL DEFAULT false;
ALTER TABLE t_5a3ce63e ADD CONSTRAINT k_1d789d69 CHECK (c_a9f03684 BETWEEN 1 AND 3 AND (c_a9f03684 & 2 = 0 OR c_b205a259 IS NOT NULL));

CREATE TABLE t_a26c5ae3 (
    c_1a157dee uuid NOT NULL,
    c_b1b16005 uuid NOT NULL,
    c_b751d80c bytea NOT NULL,
    c_70c9030a smallint NOT NULL,
    c_b8c515d3 smallint NOT NULL,
    c_2bf89cb3 bytea NOT NULL,
    c_12b3fd8a timestamptz NOT NULL,
    c_abbd22fd timestamptz NOT NULL,
    c_04741b5b integer NOT NULL DEFAULT 0,
    c_d1c00f88 timestamptz NULL,
    CONSTRAINT k_a830ba47 PRIMARY KEY (c_1a157dee),
    CONSTRAINT k_282da7e6 FOREIGN KEY (c_b1b16005) REFERENCES t_fc83d26e (c_74b9e5ad),
    CONSTRAINT k_5a1d430f UNIQUE (c_b751d80c),
    CONSTRAINT k_c954c2d6 CHECK (octet_length(c_b751d80c) = 32 AND octet_length(c_2bf89cb3) = 32 AND c_70c9030a IN (0, 1, 2)
        AND c_b8c515d3 IN (0, 1) AND c_04741b5b >= 0 AND c_abbd22fd > c_12b3fd8a)
);
CREATE INDEX k_641b8f67 ON t_a26c5ae3 (c_b1b16005, c_abbd22fd);

-- a challenge never changes who or what it is for, is consumed at most once, and its attempt counter only grows
CREATE FUNCTION f_38fce2ee() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    IF NEW.c_1a157dee IS DISTINCT FROM OLD.c_1a157dee OR NEW.c_b1b16005 IS DISTINCT FROM OLD.c_b1b16005 OR NEW.c_b751d80c IS DISTINCT FROM OLD.c_b751d80c
       OR NEW.c_70c9030a IS DISTINCT FROM OLD.c_70c9030a OR NEW.c_b8c515d3 IS DISTINCT FROM OLD.c_b8c515d3
       OR NEW.c_2bf89cb3 IS DISTINCT FROM OLD.c_2bf89cb3 OR NEW.c_12b3fd8a IS DISTINCT FROM OLD.c_12b3fd8a
       OR NEW.c_abbd22fd IS DISTINCT FROM OLD.c_abbd22fd THEN
        RAISE EXCEPTION 'the identity of a challenge is immutable';
    END IF;
    IF OLD.c_d1c00f88 IS NOT NULL AND NEW.c_d1c00f88 IS DISTINCT FROM OLD.c_d1c00f88 THEN RAISE EXCEPTION 'a challenge is consumed at most once'; END IF;
    IF NEW.c_04741b5b < OLD.c_04741b5b THEN RAISE EXCEPTION 'the attempt counter of a challenge never decreases'; END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER r_a4a064a3 BEFORE UPDATE OR DELETE ON t_a26c5ae3 FOR EACH ROW EXECUTE FUNCTION f_38fce2ee();
REVOKE ALL ON TABLE t_a26c5ae3 FROM PUBLIC;
